node -e 'const fs=require("fs"),path=require("path")
const fail=(m)=>{console.error(m);process.exit(1)}
const norm=(s)=>s.replace(/\/\*[\s\S]*?\*\//g," ").replace(/^\s*\/\/.*$/gm," ")
const rd=(f)=>{try{return norm(fs.readFileSync(f,"utf8"))}catch(e){return null}}
const q=rd("lib/library/quota.ts")
if(q===null)process.exit(79)
const g=q.indexOf("export async function loomAdmits(")
if(g<0)fail("there is no one budget gate, so each Space write door would have to re-assemble the cap, the sum and the verdict itself, and two of them never did")
const gb=q.slice(g,q.indexOf("\n}\n",g))
if(!/loomQuotaFor\(/.test(gb)||!/loomStorageUsed\(/.test(gb)||!/loomBudgetVerdict\(/.test(gb))fail("the budget gate does not ask the cap, the sum and the verdict, so it can admit a write the budget would refuse")
if(!/getSpaceById\(/.test(gb))fail("the budget gate does not read the owning Space, so it cannot tell a capped Space from the root")
const walk=(d)=>{let out=[];for(const e of fs.readdirSync(d,{withFileTypes:true})){const p=path.join(d,e.name);if(e.isDirectory()){if(e.name!=="node_modules")out=out.concat(walk(p))}else if(/\.tsx?$/.test(e.name)&&!/\.test\.tsx?$/.test(e.name))out.push(p)}return out}
const ROOT_ONLY=["app/(main)/admin/library/actions.ts","app/(main)/admin/library/recraft-actions.ts","lib/email-studio/loom-actions.ts"]
const picker=rd("lib/loom/picker-actions.ts")
if(!picker||!/return uploadAuthorizedLoomImage\(spaceId, caller\.id, formData\)/.test(picker))fail("the authorized Space picker no longer delegates to the canonical upload pipeline")
const writers=[]
for(const f of walk("app").concat(walk("lib"))){const s=rd(f);if(!s||!/\.upload\(/.test(s))continue;if(!/insertSpaceLibraryImage\(|from\(["\x27]library_assets["\x27]\)\s*\.insert\(/.test(s))continue;writers.push(f)}
for(const d of ["lib/loom/authorized-image-upload.ts","lib/page-editor/loom-field-actions.ts","lib/loom/cover-actions.ts"])if(!writers.includes(d))fail(d+" no longer stores and files a Loom image, so this probe no longer sees the door it guards; re-point it")
for(const f of writers){const s=rd(f)
if(ROOT_ONLY.includes(f)){if(!/getRootSpaceId\(/.test(s)||/getSpaceBySlug\(|getSpaceById\(|spaceForScopeKey\(/.test(s))fail(f+" is listed as writing only the uncapped root Loom but no longer resolves only the root, so it can write a capped Space with no budget");continue}
const parts=s.split(/\nexport (?=async function )/).slice(1)
for(const p of parts){const up=p.indexOf(".upload(");if(up<0)continue;const name=p.slice(15,p.indexOf("("));const gate=p.indexOf("loomAdmits(")
if(gate<0||gate>up)fail(f+" "+name+" stores bytes into a Space Loom without asking the budget first, so that Space can fill the shared bucket past its cap")
if(!/if \(!(\w+)\.ok\) return (\{ error: \1\.error \}|fail\(\1\.error\))/.test(p))fail(f+" "+name+" asks the budget but does not return its refusal, so a full Loom still stores")}}
console.log("ok "+writers.length+" writers")'
